// The wrapper tests (ada/tests/simd, generated by oracle/gen.py) cover
// exactly the methods that the generator can emit.
func TestX86MethodTable(tt *testing.T) {
	f, err := os.Open(filepath.Join("..", "..", "ada", "tests", "simd", "x86_methods.list"))
	if err != nil {
		tt.Fatal(err)
	}
	defer f.Close()
	got := []string(nil)
	s := bufio.NewScanner(f)
	for s.Scan() {
		line := s.Text()
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		got = append(got, strings.Fields(line)[0])
	}
	if err := s.Err(); err != nil {
		tt.Fatal(err)
	}
	sort.Strings(got)
	want := X86MethodNames()
	if strings.Join(got, "\n") != strings.Join(want, "\n") {
		tt.Errorf("ada/tests/simd/x86_methods.list does not list the generator's methods:\ngot  %v\nwant %v",
			got, want)
	}
	// Each method's Ada subprogram exists in its package.
	for _, key := range want {
		m := x86Methods[key]
		file := "wuffs-runtime-x86-sse42.ads"
		if m.pkg == avx2Pkg {
			file = "wuffs-runtime-x86-avx2.ads"
		}
		src, err := os.ReadFile(filepath.Join("..", "..", "ada", "src", "simd", file))
		if err != nil {
			tt.Fatal(err)
		}
		name := x86AdaName(key[strings.IndexByte(key, '.')+1:])
		if !strings.Contains(string(src), " "+name+" (") && !strings.Contains(string(src), " "+name+"\n") &&
			!strings.Contains(string(src), " "+name+" return") {
			tt.Errorf("%s: no subprogram %s in %s", key, name, file)
		}
	}
}

func readStd(tt *testing.T, dir string, names ...string) [][]byte {
	srcs := [][]byte(nil)
	for _, name := range names {
		src, err := os.ReadFile(filepath.Join("..", "..", "wuffs", "std", dir, name))
		if os.IsNotExist(err) {
			tt.Skip("no Wuffs checkout at ./wuffs")
		} else if err != nil {
			tt.Fatal(err)
		}
		srcs = append(srcs, src)
	}
	return srcs
}

// With SIMD, the x86 implementations go to child units and the ARM ones are
// still skipped; the choose statement asks the CPU.
func TestSIMDCrc32(tt *testing.T) {
	names := []string{"common_crc32.wuffs", "common_up_arm_crc32.wuffs", "common_up_x86_sse42.wuffs"}
	out, err := generate(Options{PackageName: "crc32", SIMD: true}, names, readStd(tt, "crc32", names...))
	if err != nil {
		tt.Fatal(err)
	}
	if got, want := strings.Join(out.Skipped, " "), "ieee_hasher.up_arm_crc32"; got != want {
		tt.Errorf("skipped: got %q, want %q", got, want)
	}
	if len(out.Children) != 1 || out.Children[0].UnitName != "Wuffs.Std.Crc32.X86_SSE42" {
		tt.Fatalf("children: got %d, want Wuffs.Std.Crc32.X86_SSE42", len(out.Children))
	}
	c := out.Children[0]
	for _, s := range []string{"private package Wuffs.Std.Crc32.X86_SSE42 with Preelaborate is",
		"procedure Up_X86_Sse42 (Self : in out Ieee_Hasher; A_X : Wuffs.Bytes);"} {
		if !strings.Contains(string(c.Spec), s) {
			tt.Errorf("child spec does not contain %q", s)
		}
	}
	for _, s := range []string{"Wuffs.Runtime.X86.SSE42.Mm_Clmulepi64_Si128", "Imm8 => 17", "IEEE_TABLE (0)"} {
		if !strings.Contains(string(c.Body), s) {
			tt.Errorf("child body does not contain %q", s)
		}
	}
	for _, s := range []string{
		"if Wuffs.Runtime.CPU.Have_X86_SSE42 then\n            Self.G_Choosy_Up := 1;\n         end if;",
		"Wuffs.Std.Crc32.X86_SSE42.Up_X86_Sse42 (Self => Self, A_X => A_X);",
		"with Wuffs.Std.Crc32.X86_SSE42;"} {
		if !strings.Contains(string(out.Body), s) {
			tt.Errorf("body does not contain %q", s)
		}
	}
	if strings.Contains(string(out.Body), "Up_Arm_Crc32") || strings.Contains(string(out.Body), "Mm_") {
		tt.Errorf("the package body has ARM or SIMD code")
	}
	// The table moved to the spec, where the child sees it.
	if !strings.Contains(string(out.Spec), "IEEE_TABLE : constant") || strings.Contains(string(out.Body), "IEEE_TABLE : constant") {
		tt.Errorf("IEEE_TABLE is not (only) in the spec")
	}
}

// A choose with a SIMD alternative followed by one without a requirement
// is an if-else; with only SIMD alternatives, an if without else (the
// current choice stays, as in C).
func TestSIMDChooseChains(tt *testing.T) {
	names := []string{"common_consts.wuffs", "decode_filter_arm_neon.wuffs", "decode_filter_fallback.wuffs",
		"decode_filter_x86_sse42.wuffs", "decode_png.wuffs", "decode_swizzle_default.wuffs",
		"decode_swizzle_tricky.wuffs"}
	srcs := readStd(tt, "png", names...)
	root := filepath.Join("..", "..")
	out, err := generate(Options{PackageName: "png", PackageID: 1, SIMD: true,
		ResolveUse: UseResolver(filepath.Join(root, "wuffs"))}, names, srcs)
	if err != nil {
		tt.Fatal(err)
	}
	want := "if Wuffs.Runtime.CPU.Have_X86_SSE42 then Self.G_Choosy_Filter_4 := 1; " +
		"else Self.G_Choosy_Filter_4 := 2; end if;"
	if !strings.Contains(strings.Join(strings.Fields(string(out.Body)), " "), want) {
		tt.Errorf("body does not contain %q", want)
	}
	if got := strings.Join(out.Skipped, " "); !strings.Contains(got, "arm_neon") || strings.Contains(got, "x86") {
		tt.Errorf("skipped: %q", got)
	}
}

func TestRejectsSIMD(tt *testing.T) {
	const prelude = "pub struct foo? (\n    x : base.u32,\n    a : array[32] base.u8,\n)\n" +
		"pub func foo.go!() {\n    choose up = [up_sse42]\n    this.up!()\n}\n" +
		"pri func foo.up!(), choosy, {\n    this.x = 0\n}\n"
	testCases := []struct{ what, src, want string }{{
		what: "unsupported method",
		src: `pri func foo.up_sse42!(), choose cpu_arch >= x86_sse42, {
				var util : base.x86_sse42_utility
				var v : base.x86_m128i
				v = util.make_m128i_zeroes()
				v = v._mm_max_epi16(b: v)
				this.x = v.truncate_u32()
			}`,
		want: "not yet supported: the cpu_arch method x86_m128i._mm_max_epi16",
	}, {
		what: "immediate out of range",
		src: `pri func foo.up_sse42!(), choose cpu_arch >= x86_sse42, {
				var util : base.x86_sse42_utility
				var v : base.x86_m128i
				v = util.make_m128i_zeroes()
				this.x = v._mm_extract_epi32(imm8: 4)
			}`,
		want: "argument imm8 must be a constant in 0 ..= 3",
	}, {
		what: "immediate not constant",
		src: `pri func foo.up_sse42!(), choose cpu_arch >= x86_sse42, {
				var util : base.x86_sse42_utility
				var v : base.x86_m128i
				v = util.make_m128i_zeroes()
				v = v._mm_slli_epi32(imm8: this.x)
				this.x = v.truncate_u32()
			}`,
		want: "argument imm8 must be a constant in 0 ..= 255",
	}, {
		what: "AVX2 method in an SSE4.2 function",
		src: `pri func foo.up_sse42!(), choose cpu_arch >= x86_sse42, {
				var util : base.x86_avx2_utility
				var v : base.x86_m256i
				v = util.make_m256i_slice_u16lex16(a: this.b[0 .. 16])
				this.x = 0
			}`,
		want: "needs more than x86_sse42",
	}}
	for _, tc := range testCases {
		src := prelude + tc.src + "\n"
		if strings.Contains(tc.src, "this.b[") {
			src = strings.Replace(src, "a : array[32] base.u8,", "a : array[32] base.u8,\n    b : array[16] base.u16,", 1)
		}
		out, err := generate(Options{PackageName: "pkg", PackageID: 9, SIMD: true}, []string{"test.wuffs"},
			[][]byte{[]byte(src)})
		if err == nil {
			tt.Errorf("%s: got no error, want one containing %q. Output:\n%s", tc.what, tc.want, out.Body)
		} else if !strings.Contains(err.Error(), tc.want) {
			tt.Errorf("%s: got error %q, want one containing %q", tc.what, err, tc.want)
		}
	}

	// Without SIMD the same function is skipped, whatever it calls.
	src := prelude + `pri func foo.up_sse42!(), choose cpu_arch >= x86_sse42, {
				var util : base.x86_sse42_utility
				var v : base.x86_m128i
				v = util.make_m128i_zeroes()
				v = v._mm_max_epi16(b: v)
				this.x = v.truncate_u32()
			}` + "\n"
	out, err := generate(Options{PackageName: "pkg", PackageID: 9}, []string{"test.wuffs"}, [][]byte{[]byte(src)})
	if err != nil {
		tt.Fatalf("without SIMD: %v", err)
	}
	if got := strings.Join(out.Skipped, " "); got != "foo.up_sse42" || len(out.Children) != 0 {
		tt.Errorf("without SIMD: skipped %q, %d children", got, len(out.Children))
	}
}
